package com.smartspend.controller;
import com.smartspend.service.AuthService;import com.smartspend.util.*;import javafx.geometry.*;import javafx.scene.control.*;import javafx.scene.layout.*;import javafx.stage.Stage;
public class RegisterView extends BorderPane {private final AuthService auth=new AuthService();private final TextField name=UI.input("Full name"),email=UI.input("Email address");private final PasswordField pass=UI.password("Password (8+ characters)"),confirm=UI.password("Confirm password");private final Stage stage;
 public RegisterView(Stage stage,Runnable back){this.stage=stage;setPadding(new Insets(50));getStyleClass().add("auth-bg");VBox box=new VBox(16);box.setMaxWidth(430);Label logo=new Label("◆ SMARTSPEND");logo.getStyleClass().add("logo");Label h=new Label("Create your account");h.getStyleClass().add("auth-title");Label sub=UI.subtitle("Your finances, organized and easier to understand.");Button create=UI.button("Create Account");create.setMaxWidth(Double.MAX_VALUE);Button b=UI.ghost("← Back to login");create.setOnAction(e->doRegister());b.setOnAction(e->back.run());box.getChildren().addAll(logo,h,sub,name,email,pass,confirm,create,b);setCenter(new StackPane(box));}
 private void doRegister(){try{auth.register(name.getText(),email.getText(),pass.getText(),confirm.getText());UI.alert(stage,"Account created","Your SmartSpend account is ready. You can now log in.");stage.getScene().setRoot(new LoginView(stage,()->stage.getScene().setRoot(this)));}catch(Exception e){UI.error(stage,e.getMessage());}}
}
